import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const n=JSON.parse('{"title":"wujie 2 · 页签核心与异构子应用主微前端模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/wujie.md","filePath":"modules/catalog/wujie.md","lastUpdated":1795182147000}'),c={name:"modules/catalog/wujie.md"};function r(i,e,l,u,s,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="wujie-2-·-页签核心与异构子应用主微前端模板" tabindex="-1">wujie 2 · 页签核心与异构子应用主微前端模板 <a class="header-anchor" href="#wujie-2-·-页签核心与异构子应用主微前端模板" aria-label="Permalink to &quot;wujie 2 · 页签核心与异构子应用主微前端模板&quot;">​</a></h1><p>页签核心由框架无关的 <code>libs-wujie2-tabs-core</code> 管理，Vue 3 宿主可以使用内置 Tab 栏或自定义样式。主应用（Vue 3 / CLI 5）通过 <code>wujie-vue3</code> 以 <code>alive</code> 模式挂载 4 个异构子应用，覆盖 Vue 3 CLI 5、Vue 3 Vite、Vue 2.7 CLI 4 与 React 18 Vite 三种框架、两种构建链。</p><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-wujie2-tabs-core</code></td><td>框架无关层：页签状态机（runtime）、页签 id 编解码（<code>tab-id</code>）、页面级保活判定（<code>page-cache</code>），不持有 Wujie 实例</td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-vue3</code></td><td>Vue 3 适配层，提供无头 <code>WujieTabBar</code> 与 <code>useWujieTabs</code></td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-vue2</code></td><td>Vue 2.7 适配层，API 与 Vue 3 版一致，组件销毁时自动退订</td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-react</code></td><td>React 18 适配层，<code>useWujieTabs</code> 基于 <code>useSyncExternalStore</code>，附 <code>children</code> 渲染函数的无头组件</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-cli5-main</code></td><td>Vue 3 主应用（Vue CLI 5 / webpack 5），托管 4 个子应用并维护菜单与页签</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-cli5-app1</code></td><td>Vue 3 子应用（Vue CLI 5，Element Plus / Ant Design Vue 页面）</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-vite-app2</code></td><td>Vue 3 子应用（Vite）</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue2-cli4-app3</code></td><td>Vue 2.7 子应用（Vue CLI 4 / webpack 4，Element UI）</td></tr><tr><td><code>@melt-js/tpl-wujie2-react-vite-app4</code></td><td>React 18 子应用（Vite 6，Ant Design）</td></tr></tbody></table><p>仅兼容 wujie 2，不做 wujie 1 兼容。主应用可使用适配包的普通入口，也可以通过 HEL 加载远程页签。</p><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-wujie2-vue3-cli5-main</code></td><td><a href="https://melt-js.github.io/tpl-wujie2-vue3-cli5-main/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue3-cli5-app1</code></td><td><a href="https://melt-js.github.io/tpl-wujie2-vue3-cli5-app1/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue3-vite-app2</code></td><td><a href="https://melt-js.github.io/tpl-wujie2-vue3-vite-app2/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue2-cli4-app3</code></td><td><a href="https://melt-js.github.io/tpl-wujie2-vue2-cli4-app3/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-react-vite-app4</code></td><td><a href="https://melt-js.github.io/tpl-wujie2-react-vite-app4/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><p>子应用单独打开时是独立页面，只有通过主应用进入才能验证页签、保活与路由同步。</p><h2 id="在主应用体验" tabindex="-1">在主应用体验 <a class="header-anchor" href="#在主应用体验" aria-label="Permalink to &quot;在主应用体验&quot;">​</a></h2><p>从左侧展开一个子应用，分别打开标记「保活」的页面和「临时表单」。在两页分别输入内容并切换回来，对比内容是否保留。「Wujie API 演示」可查看路由同步、Tab 操作与主子应用消息。</p><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>core：<code>createWujieTabs({ initialTabs })</code></td><td>创建页签管理器，<code>pinned</code> 页签在关闭操作中始终保留</td></tr><tr><td>core：<code>open(tab)</code></td><td>按 <code>id</code> 去重并激活；同一应用有多个页面时用合成 ID，完整路径保存在 <code>fullPath</code></td></tr><tr><td>core：<code>activate(id)</code> / <code>activate(null)</code></td><td>切换已打开页签，传 <code>null</code> 清除选中</td></tr><tr><td>core：<code>getState()</code> / <code>subscribe(listener)</code></td><td>只读快照与变更订阅，<code>subscribe</code> 返回取消订阅函数</td></tr><tr><td>core：<code>close(id)</code> / <code>closeOthers(id)</code> / <code>closeAll()</code></td><td>关闭单个或批量关闭；关闭当前项时优先选右侧相邻，其次左侧</td></tr><tr><td>core：<code>getCloseFallback(id)</code></td><td>提前取得关闭当前页签后的候选项</td></tr><tr><td>Vue 3：<code>WujieTabBar</code></td><td>无头组件，只渲染默认插槽，DOM、样式与键盘交互由宿主决定</td></tr><tr><td>Vue 3：<code>useWujieTabs(manager)</code></td><td>在 <code>setup</code> 内取得只读响应式快照，操作仍走同一个 manager</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>WujieTabBar</code>（Vue 3）</td><td>默认插槽暴露 <code>tabs</code>、<code>activeId</code>、<code>activate</code>、<code>close</code>、<code>closeOthers</code>、<code>closeAll</code></td></tr></tbody></table><p>页面级 Tab 栏、菜单与 API 演示页都在主应用内维护，不作为独立组件导出。</p><h2 id="接入页签" tabindex="-1">接入页签 <a class="header-anchor" href="#接入页签" aria-label="Permalink to &quot;接入页签&quot;">​</a></h2><ol><li>在 Vue 3 主应用中加载 <code>libs-wujie2-tabs-vue3</code> 的 HEL 元数据，等待 <code>createTabsAdapter</code> 就绪，再导入业务入口。参见<a href="./../../guide/micro-frontend-tabs.html#在主应用加载页签">主应用预加载示例</a>。</li><li>从 <code>@melt-js/libs-wujie2-tabs-vue3/remote</code> 导入 <code>createTabsManager</code> 和 <code>DynamicTabsComponent</code>。创建一个管理器实例，传给布局的 Tab 组件。应用也可以用默认入口的无头 <code>WujieTabBar</code> 绘制自己的 Tab 栏。</li><li>主应用注册 <code>wujie-vue3</code>，配置每个子应用的 <code>name</code>、<code>url</code>。需要应用保活时，预取和挂载视图都设置 <code>alive: true</code>。不同页面共用一个子应用时，页签 ID 使用「应用名 + 页面路径」，<code>fullPath</code> 则保留 query 与 hash。等路由成功后再更新当前页签。</li><li>子应用通过自己的路由渲染。要控制页面级保活，主应用可用 Wujie 的 <code>bus</code> 广播当前页签的应用名与路径；子应用收到后，对 <code>keepAlive: false</code> 的页面只在当前页签激活时挂载。模板仅在关闭某子应用的最后一个页签时销毁其沙箱。</li></ol><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>主应用基于 wujie 2 的 Vue 3 使用方式（<code>wujie-vue3</code> + <code>bus</code>），菜单与路由统一由主应用维护，并标记各页面是否保活。主应用侧对齐 qiankun 模板的示例结构，含首页、关于（带 query）、用户、临时表单（不保活）、页面守卫演示、Wujie API 演示六项，其中“页面守卫演示”展示 <code>router.beforeEach</code> 的二次确认拦截。四个子应用各自提供“关于 / 用户 / 临时表单（不保活）”三个页面，每个子应用都能就地对照保活与不保活的状态差异：保活页切换页签后输入仍在，临时表单切走后重新创建、输入清空。页面状态用输入探针验证，主应用“Wujie API 演示”页覆盖 Tab 操作、主子应用路由同步与 <code>bus</code> 双向通信。</p>',19)])])}const p=t(c,[["render",r]]);export{n as __pageData,p as default};
